from itertools import product

def count_wins(die_a, die_b):
    """Count how many (a,b) pairs where die_a face > die_b face"""
    wins = 0
    for a in die_a:
        for b in die_b:
            if a > b:
                wins += 1
    return wins

# Let's try a direct search approach with some known constructions
# For Efron-style dice with values in {0,...,11}

# First, let's try a Z3-based approach
from z3 import *

# 5 dice, 6 faces each
faces = [[Int(f'die_{i}_face_{j}') for j in range(6)] for i in range(5)]

solver = Solver()

# Each face value in {0, ..., 11}
for i in range(5):
    for j in range(6):
        solver.add(faces[i][j] >= 0, faces[i][j] <= 11)

# Faces sorted in ascending order (symmetry breaking)
for i in range(5):
    for j in range(5):
        solver.add(faces[i][j] <= faces[i][j+1])

# Cyclic intransitivity: die i beats die (i+1) mod 5
# #{(a,b): face(i,a) > face((i+1)%5, b)} > 18
for i in range(5):
    next_i = (i + 1) % 5
    # Count wins using sum of indicator variables
    win_count = Sum([
        If(faces[i][a] > faces[next_i][b], 1, 0)
        for a in range(6)
        for b in range(6)
    ])
    solver.add(win_count > 18)

print("Solving with Z3...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    model = solver.model()
    solution = []
    for i in range(5):
        die = sorted([model[faces[i][j]].as_long() for j in range(6)])
        solution.extend(die)
        print(f"Die {i}: {die}")

    # Verify
    print("\nVerification:")
    for i in range(5):
        next_i = (i + 1) % 5
        die_a = solution[i*6:(i+1)*6]
        die_b = solution[next_i*6:(next_i+1)*6]
        wins = count_wins(die_a, die_b)
        print(f"Die {i} vs Die {next_i}: {wins}/36 wins ({'BEATS' if wins > 18 else 'FAILS'})")
